def get_pokemon(species_id):
    return POKEMON_DATA.get(species_id)

def get_ability(species_id, ability_number):
    pokemon = get_pokemon(species_id)
    if pokemon is None:
        return 'Unknown'
    abilities = pokemon['abilities']
    index = 1 if ability_number else 0
    return abilities[index] or abilities[0] or 'Unknown'
